template:
// LONGEST window satisfying a monotone condition: at most k distinct characters.
int longestAtMostKDistinct(const string& s, int k) {
    unordered_map<char,int> cnt;        // the incremental summary of the window
    int best = 0;
    for (int l = 0, r = 0; r < (int)s.size(); ++r) {
        cnt[s[r]]++;                                   // 1. add the new right element
        while ((int)cnt.size() > k) {                  // 2. window broke the rule → shrink
            if (--cnt[s[l]] == 0) cnt.erase(s[l]);
            ++l;
        }
        best = max(best, r - l + 1);                   // 3. window is valid here
    }
    return best;
}

// SHORTEST window with sum >= target (positives only).
int shortestSumAtLeast(const vector<int>& a, int target) {
    long long sum = 0;
    int best = INT_MAX;
    for (int l = 0, r = 0; r < (int)a.size(); ++r) {
        sum += a[r];
        while (sum >= target) {                        // valid → record, then try to shrink
            best = min(best, r - l + 1);
            sum -= a[l++];
        }
    }
    return best == INT_MAX ? 0 : best;
}

